BROOMVA_OWNER_PATHS=".broomva/policy.yaml .control/policy.yaml .broomva/preauth.yaml .control/preauth.yaml .broomva/allowed_signers .control/allowed_signers .broomva/hooks"

# _broomva_repo_entry NAME -> "PATH HAS_LEGACY" (1 or 0)
_broomva_repo_entry() {
    case "${1#repo.}" in
        policy) printf '%s\n' 'policy.yaml 1' ;;
        preauth) printf '%s\n' 'preauth.yaml 1' ;;
        allowed_signers) printf '%s\n' 'allowed_signers 1' ;;
        hooks) printf '%s\n' 'hooks 0' ;;
        asks) printf '%s\n' 'asks 1' ;;
        initiatives) printf '%s\n' 'initiatives 1' ;;
        arcs) printf '%s\n' 'arcs.yaml 1' ;;
        bands) printf '%s\n' 'bands 1' ;;
        loops) printf '%s\n' 'loops 0' ;;
        checks) printf '%s\n' 'checks 0' ;;
        rcs_parameters) printf '%s\n' 'rcs-parameters.toml 1' ;;
        leverage_setpoints) printf '%s\n' 'leverage-setpoints.yaml 1' ;;
        hillclimb) printf '%s\n' 'hillclimb 1' ;;
        spec_contract_grandfathered) printf '%s\n' 'spec-contract-grandfathered.txt 1' ;;
        i2p_profile_example) printf '%s\n' 'i2p-profile.example.json 1' ;;
        commands) printf '%s\n' 'commands.yaml 1' ;;
        topology) printf '%s\n' 'topology.yaml 1' ;;
        state) printf '%s\n' 'state.json 1' ;;
        plant) printf '%s\n' 'plant.yaml 1' ;;
        runtime) printf '%s\n' 'runtime.yaml 1' ;;
        problem_spec_template) printf '%s\n' 'problem-spec.template.yaml 1' ;;
        egri) printf '%s\n' 'egri.yaml 1' ;;
        egri_journal) printf '%s\n' 'egri-journal.jsonl 1' ;;
        evals) printf '%s\n' 'evals 1' ;;
        schemas) printf '%s\n' 'schemas 1' ;;
        audit) printf '%s\n' 'audit 1' ;;
        leverage_metrics) printf '%s\n' 'leverage-metrics.jsonl 1' ;;
        leverage_state) printf '%s\n' 'leverage-state.json 1' ;;
        leverage_ship_state) printf '%s\n' 'leverage-ship-state.json 1' ;;
        *) return 2 ;;
    esac
}

# _broomva_machine_entry NAME -> "PATH LEGACY" (LEGACY is - when none)
_broomva_machine_entry() {
    case "${1#machine.}" in
        config) printf '%s\n' 'config -' ;;
        secrets) printf '%s\n' 'secrets -' ;;
        ledger) printf '%s\n' 'ledger -' ;;
        loop_ticks) printf '%s\n' 'ledger/loops/ticks.jsonl -' ;;
        work) printf '%s\n' 'work ~/maestro' ;;
        runs) printf '%s\n' 'runs -' ;;
        notes) printf '%s\n' 'notes -' ;;
        views) printf '%s\n' 'views -' ;;
        index) printf '%s\n' 'index -' ;;
        cache) printf '%s\n' 'cache -' ;;
        locks) printf '%s\n' 'locks -' ;;
        state) printf '%s\n' 'state -' ;;
        data) printf '%s\n' 'data -' ;;
        releases) printf '%s\n' 'releases -' ;;
        logs) printf '%s\n' 'logs -' ;;
        *) return 2 ;;
    esac
}

broomva_machine_root() {
    if [ -n "${BROOMVA_HOME:-}" ]; then printf '%s\n' "$BROOMVA_HOME"; else printf '%s\n' "$HOME/.broomva"; fi
}

broomva_workspace_root() {
    if [ -n "${BROOMVA_WORKSPACE:-}" ]; then printf '%s\n' "$BROOMVA_WORKSPACE"
    elif [ -n "${MAESTRO_WORKSPACE:-}" ]; then printf '%s\n' "$MAESTRO_WORKSPACE"
    elif [ -n "${BSTACK_WORKSPACE:-}" ]; then printf '%s\n' "$BSTACK_WORKSPACE"
    else printf '%s\n' "$HOME/broomva"; fi
}

# broomva_repo_root [TARGET] -> the git top level of TARGET (else of
# $CLAUDE_PROJECT_DIR); fails outside a repo, and when $HOME is that top level.
broomva_repo_root() {
    _br_t=${1:-${CLAUDE_PROJECT_DIR:-}}
    [ -n "$_br_t" ] || return 1
    [ -d "$_br_t" ] || _br_t=$(dirname "$_br_t")
    while [ ! -d "$_br_t" ] && [ "$_br_t" != "/" ]; do _br_t=$(dirname "$_br_t"); done
    _br_top=$(git -C "$_br_t" rev-parse --show-toplevel 2>/dev/null) || return 1
    [ -n "$_br_top" ] || return 1
    if [ "$(cd "$_br_top" && pwd -P)" = "$(cd "$HOME" && pwd -P)" ]; then return 1; fi
    printf '%s\n' "$_br_top"
}

# broomva_repo_rels NAME -> the repo-relative paths NAME may hold, new first
broomva_repo_rels() {
    _br_e=$(_broomva_repo_entry "$1") || return 2
    printf '%s\n' "$BROOMVA_REPO_DIR/${_br_e% *}"
    [ "${_br_e##* }" = 1 ] && printf '%s\n' "$BROOMVA_REPO_LEGACY_DIR/${_br_e% *}"
    return 0
}

# broomva_repo_path NAME ROOT -> where NAME lives on disk in the repo at ROOT
broomva_repo_path() {
    _br_e=$(_broomva_repo_entry "$1") || return 2
    _br_p=${_br_e% *}
    _br_new="$2/$BROOMVA_REPO_DIR/$_br_p"
    _br_old="$2/$BROOMVA_REPO_LEGACY_DIR/$_br_p"
    if [ -e "$_br_new" ] || [ "${_br_e##* }" = 0 ]; then printf '%s\n' "$_br_new"
    elif [ -e "$_br_old" ] || [ -d "$2/$BROOMVA_REPO_LEGACY_DIR" ]; then printf '%s\n' "$_br_old"
    else printf '%s\n' "$_br_new"; fi
}

broomva_workspace_path() {
    broomva_repo_path "${1#workspace.}" "$(broomva_workspace_root)"
}

# broomva_machine_path NAME -> where NAME lives under $BROOMVA_HOME (or its legacy)
broomva_machine_path() {
    _br_e=$(_broomva_machine_entry "$1") || return 2
    _br_new="$(broomva_machine_root)/${_br_e% *}"
    _br_old=${_br_e##* }
    case "$_br_old" in \~/*) _br_old="$HOME/${_br_old#\~/}" ;; esac
    if [ -e "$_br_new" ] || [ "$_br_old" = - ] || [ ! -e "$_br_old" ]; then printf '%s\n' "$_br_new"
    else printf '%s\n' "$_br_old"; fi
}

# broomva_tree_path NAME ROOT [REV] -> the path NAME has in git tree REV (default HEAD)
broomva_tree_path() {
    _br_rev=${3:-HEAD}
    case "$_br_rev" in -*|"") return 2 ;; esac
    for _br_rel in $(broomva_repo_rels "$1") ; do
        if git -C "$2" cat-file -e "$_br_rev:$_br_rel" 2>/dev/null; then printf '%s\n' "$_br_rel"; return 0; fi
    done
    return 1
}
